// The error trigger hands us the failed execution. Build a Slack alert that
// says enough to act on without opening n8n: which workflow, which node, why.
const j = $input.first().json;
const wf = (j.workflow && j.workflow.name) || 'unknown workflow';
const ex = j.execution || {};
const node = ex.lastNodeExecuted || 'unknown node';
const msg = (ex.error && (ex.error.message || ex.error.description)) || 'no error message';
const url = ex.url || '';

const blocks = [
  { type: 'header',
    text: { type: 'plain_text', text: 'Brand check failed' } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Workflow*\n${wf}` },
    { type: 'mrkdwn', text: `*Failed at*\n${node}` },
  ]},
  { type: 'section',
    text: { type: 'mrkdwn', text: `*Reason*\n\`\`\`${String(msg).slice(0, 800)}\`\`\`` } },
];
if (url) {
  blocks.push({ type: 'actions', elements: [
    { type: 'button', text: { type: 'plain_text', text: 'Open execution in n8n' },
      url, action_id: 'open_execution' },
  ]});
}
blocks.push({ type: 'context', elements: [
  { type: 'mrkdwn', text: 'Nothing was sent to the requester. The draft above is still actionable once this is fixed.' },
]});

return [{ json: { channel: 'C0BFLT4M3FF', text: `Brand check failed: ${wf} at ${node}`, blocks } }];
